using System.Data;
using System.Text.Json;
namespace Finance.Core;
public partial class Engine
{
    const string InvoiceQuery="SELECT i.Id,i.Day AS Date,i.Kind,i.Number,p.Name AS Party,i.DueDay AS [Due Date],i.PlaceOfSupply,i.Taxable AS [Taxable (INR)],i.CGST AS [CGST (INR)],i.SGST AS [SGST (INR)],i.IGST AS [IGST (INR)],i.Total AS [Total (INR)],i.Total-COALESCE((SELECT SUM(a.Amount) FROM Allocation a JOIN Voucher v ON v.Id=a.VoucherId WHERE a.InvoiceId=i.Id AND v.Day<=@p1 AND (v.ReversedBy IS NULL OR (SELECT rv.Day FROM Voucher rv WHERE rv.Id=v.ReversedBy)>@p1)),0) AS [Outstanding (INR)],CASE WHEN (i.Cancelled=1 AND i.VoucherId IS NULL) OR EXISTS(SELECT 1 FROM Voucher ov JOIN Voucher rv ON rv.Id=ov.ReversedBy WHERE ov.Id=i.VoucherId AND rv.Day<=@p1) THEN 'Cancelled' WHEN i.VoucherId IS NULL THEN 'Draft' WHEN i.Total=COALESCE((SELECT SUM(a.Amount) FROM Allocation a JOIN Voucher v ON v.Id=a.VoucherId WHERE a.InvoiceId=i.Id AND v.Day<=@p1 AND (v.ReversedBy IS NULL OR (SELECT rv.Day FROM Voucher rv WHERE rv.Id=v.ReversedBy)>@p1)),0) THEN 'Settled' WHEN EXISTS(SELECT 1 FROM Allocation a JOIN Voucher v ON v.Id=a.VoucherId WHERE a.InvoiceId=i.Id AND v.Day<=@p1 AND (v.ReversedBy IS NULL OR (SELECT rv.Day FROM Voucher rv WHERE rv.Id=v.ReversedBy)>@p1)) THEN 'Partially Settled' ELSE 'Unpaid' END AS Status,i.Reference FROM Invoice i JOIN Party p ON p.Id=i.PartyId";
    const string LedgerQuery="SELECT p.Id,v.Id AS VoucherId,v.Day AS Date,v.Number,v.Kind,a.Name AS Account,COALESCE(pt.Name,e.Name,b.Name,'') AS Party,p.Amount AS [Amount (INR)],s.Name AS Site,ins.Number AS Instrument,c.Name AS Category,v.Narration,CASE WHEN v.ReversedBy IS NOT NULL THEN 'Reversed' WHEN v.ReversalOf IS NOT NULL THEN 'Reversal' ELSE 'Posted' END AS Status FROM Posting p JOIN Voucher v ON v.Id=p.VoucherId JOIN Account a ON a.Code=p.Account LEFT JOIN Party pt ON pt.Id=p.PartyId LEFT JOIN Employee e ON e.Id=p.EmployeeId LEFT JOIN Bank b ON b.Id=p.BankId LEFT JOIN Site s ON s.Id=p.SiteId LEFT JOIN Instrument ins ON ins.Id=p.InstrumentId LEFT JOIN Category c ON c.Id=p.CategoryId";
    public static readonly string[] ReportNames=["Transaction Register","General Ledger","Trial Balance","Profit and Loss","Balance Sheet","Sales Register","Customer Outstanding","Customer Ledger","Sales GST Summary","Sales HSN Summary","Purchase Register","Supplier Outstanding","Supplier Ledger","Purchase GST Summary","Purchase HSN Summary","Expense Register","Expense Category Summary","Site-wise Expense","Staff Advance Outstanding","Employee Advance Outstanding","Employee Loan Register","Employee Loan Recoveries","Employee Ledger","Payroll Register","Salary Payment Status","EPF Summary","ESIC Summary","Bank Book","Cash Book","Bank Balances","Bank Reconciliation","FD Register","FD Maturity","FD Lien","BG Register","BG Expiry","BG-FD Links","Business Loan Register","EMI Schedule","Alerts","Audit History","Backup History","Period Locks","Statutory History"];
    string ReportSql(string name)=>name switch{
        "Sales Register"=>InvoiceQuery+" WHERE i.Kind='Sales' AND i.Day BETWEEN @p0 AND @p1",
        "Purchase Register"=>InvoiceQuery+" WHERE i.Kind='Purchase' AND i.Day BETWEEN @p0 AND @p1",
        "Customer Outstanding"=>"SELECT * FROM ("+InvoiceQuery+" WHERE i.Kind='Sales' AND i.Day<=@p1) WHERE Status IN ('Unpaid','Partially Settled')",
        "Supplier Outstanding"=>"SELECT * FROM ("+InvoiceQuery+" WHERE i.Kind='Purchase' AND i.Day<=@p1) WHERE Status IN ('Unpaid','Partially Settled')",
        "Transaction Register"=>"SELECT v.Id,v.Day AS Date,v.Number,v.Kind,v.FY,v.Narration,SUM(CASE WHEN p.Amount>0 THEN p.Amount ELSE 0 END) AS [Amount (INR)],CASE WHEN v.ReversedBy IS NOT NULL THEN 'Reversed' WHEN v.ReversalOf IS NOT NULL THEN 'Reversal' ELSE 'Posted' END AS Status FROM Voucher v JOIN Posting p ON p.VoucherId=v.Id WHERE v.Day BETWEEN @p0 AND @p1 GROUP BY v.Id",
        "General Ledger"=>LedgerQuery+" WHERE v.Day BETWEEN @p0 AND @p1",
        "Customer Ledger"=>LedgerQuery+" WHERE p.Account IN ('AR','CUSTADV') AND v.Day BETWEEN @p0 AND @p1",
        "Supplier Ledger"=>LedgerQuery+" WHERE p.Account='AP' AND v.Day BETWEEN @p0 AND @p1",
        "Employee Ledger"=>LedgerQuery+" WHERE p.EmployeeId IS NOT NULL AND v.Day BETWEEN @p0 AND @p1",
        "Expense Register"=>LedgerQuery+" WHERE a.Category='Expense' AND v.Day BETWEEN @p0 AND @p1",
        "Employee Loan Recoveries"=>LedgerQuery+" WHERE p.Account='ELOAN' AND p.Amount<0 AND v.Day BETWEEN @p0 AND @p1",
        "Bank Book"=>LedgerQuery+" WHERE p.Account='BANK' AND b.Cash=0 AND v.Day BETWEEN @p0 AND @p1",
        "Cash Book"=>LedgerQuery+" WHERE p.Account='BANK' AND b.Cash=1 AND v.Day BETWEEN @p0 AND @p1",
        "Trial Balance"=>"SELECT a.Code AS Id,a.Name AS Account,a.Category,COALESCE(SUM(CASE WHEN v.Day<=@p1 THEN p.Amount ELSE 0 END),0) AS [Balance (INR)] FROM Account a LEFT JOIN Posting p ON p.Account=a.Code LEFT JOIN Voucher v ON v.Id=p.VoucherId GROUP BY a.Code",
        "Profit and Loss"=>"SELECT a.Code AS Id,a.Name AS Account,a.Category,SUM(p.Amount) AS [Debit less credit (INR)] FROM Posting p JOIN Account a ON a.Code=p.Account JOIN Voucher v ON v.Id=p.VoucherId WHERE a.Category IN ('Income','Expense') AND v.Day BETWEEN @p0 AND @p1 GROUP BY a.Code",
        "Balance Sheet"=>"SELECT a.Code AS Id,a.Name AS Account,a.Category,SUM(p.Amount) AS [Debit less credit (INR)] FROM Posting p JOIN Account a ON a.Code=p.Account JOIN Voucher v ON v.Id=p.VoucherId WHERE a.Category NOT IN ('Income','Expense') AND v.Day<=@p1 GROUP BY a.Code UNION ALL SELECT 'RESULT','Accumulated profit / loss','Equity',SUM(p.Amount) FROM Posting p JOIN Account a ON a.Code=p.Account JOIN Voucher v ON v.Id=p.VoucherId WHERE a.Category IN ('Income','Expense') AND v.Day<=@p1",
        "Bank Balances"=>"SELECT b.Id,b.Name,b.AccountNumber,CASE WHEN b.Cash=1 THEN 'Cash' ELSE 'Bank' END AS Type,COALESCE((SELECT SUM(p.Amount) FROM Posting p JOIN Voucher v ON v.Id=p.VoucherId WHERE p.BankId=b.Id AND p.Account='BANK' AND v.Day<=@p1),0) AS [Balance (INR)] FROM Bank b",
        "Staff Advance Outstanding"=>AdvanceQuery("STAFF"),"Employee Advance Outstanding"=>AdvanceQuery("ADV"),
        "Expense Category Summary"=>"SELECT c.Id,c.Name AS Category,SUM(p.Amount) AS [Expense (INR)] FROM Posting p JOIN Voucher v ON v.Id=p.VoucherId JOIN Category c ON c.Id=p.CategoryId WHERE p.Account='EXPENSE' AND v.Day BETWEEN @p0 AND @p1 GROUP BY c.Id",
        "Site-wise Expense"=>"SELECT s.Id,s.Name AS Site,SUM(p.Amount) AS [Expense (INR)] FROM Posting p JOIN Voucher v ON v.Id=p.VoucherId JOIN Site s ON s.Id=p.SiteId WHERE p.Account='EXPENSE' AND v.Day BETWEEN @p0 AND @p1 GROUP BY s.Id",
        "Sales GST Summary"=>GSTQuery("Sales",false),"Purchase GST Summary"=>GSTQuery("Purchase",false),"Sales HSN Summary"=>GSTQuery("Sales",true),"Purchase HSN Summary"=>GSTQuery("Purchase",true),
        "FD Register" or "FD Maturity"=>InstrumentQuery("FD"),"Employee Loan Register"=>InstrumentQuery("Employee Loan"),"Business Loan Register" or "EMI Schedule"=>InstrumentQuery("Business Loan"),
        "FD Lien" or "BG-FD Links"=>"SELECT l.Id,b.Number AS BG,f.Number AS FD,f.Principal AS [Principal (INR)],l.LinkedDay AS [Linked Date],l.ReleasedDay AS [Release Date],b.Status AS BGStatus,f.Status AS FDStatus FROM BGFD l JOIN BG b ON b.Id=l.BGId JOIN Instrument f ON f.Id=l.FDId",
        "BG Register" or "BG Expiry"=>"SELECT b.Id,b.Day AS Date,b.Number,b.Beneficiary,b.Amount AS [Amount (INR)],bank.Name AS Bank,b.Type,b.Purpose,b.ExpiryDay AS [Expiry Date],b.ClaimDay AS [Claim Date],b.Dispatch,b.DeliveredDay AS [Delivered Date],CASE WHEN b.Confirmed=1 THEN 'Yes' ELSE 'No' END AS Confirmed,CASE WHEN b.Status='Closed' AND EXISTS(SELECT 1 FROM BGFD l WHERE l.BGId=b.Id AND l.ReleasedDay IS NULL) THEN 'BG CLOSED — FD/LIEN RELEASE PENDING' WHEN b.Status='Closed' THEN 'Closed' WHEN b.ExpiryDay<@p1 THEN 'Expired' WHEN b.ExpiryDay<=@p1+30 THEN 'Expiring' ELSE 'Active' END AS Status FROM BG b JOIN Bank bank ON bank.Id=b.BankId",
        "Payroll Register" or "Salary Payment Status"=>"SELECT r.Id,p.Id AS PayrollId,p.Day AS Date,e.Code AS EmployeeCode,e.Name AS Employee,p.Revision,p.Status,r.Net AS [Net (INR)],r.Net-COALESCE((SELECT SUM(a.Amount) FROM SalaryAllocation a JOIN Voucher v ON v.Id=a.VoucherId WHERE a.PayrollRowId=r.Id AND v.Day<=@p1 AND (v.ReversedBy IS NULL OR (SELECT rv.Day FROM Voucher rv WHERE rv.Id=v.ReversedBy)>@p1)),0) AS [Due (INR)],r.Snapshot FROM PayrollRow r JOIN Payroll p ON p.Id=r.PayrollId JOIN Employee e ON e.Id=r.EmployeeId WHERE p.Day BETWEEN @p0 AND @p1",
        "EPF Summary"=>LedgerQuery+" WHERE p.Account='EPF' AND v.Day BETWEEN @p0 AND @p1",
        "ESIC Summary"=>LedgerQuery+" WHERE p.Account='ESIC' AND v.Day BETWEEN @p0 AND @p1",
        "Bank Reconciliation"=>"SELECT p.Id,v.Id AS VoucherId,v.Day AS Date,b.Name AS Bank,v.Number,p.Amount AS [Amount (INR)],v.Narration,r.StatementDay AS [Statement Date],r.Reference,CASE WHEN v.ReversedBy IS NOT NULL OR v.ReversalOf IS NOT NULL THEN 'Reversed' WHEN r.Id IS NULL THEN 'Unmatched' ELSE 'Reconciled' END AS Status FROM Posting p JOIN Voucher v ON v.Id=p.VoucherId JOIN Bank b ON b.Id=p.BankId LEFT JOIN Reconciliation r ON r.PostingId=p.Id WHERE p.Account='BANK' AND v.Day BETWEEN @p0 AND @p1",
        "Audit History"=>"SELECT Id,TimeUtc AS [Action Time],UserId,Entity,EntityId,Action,OldValue,NewValue,Reason FROM Audit",
        "Backup History"=>"SELECT Id,TimeUtc AS [Backup Time],File,Status FROM BackupHistory",
        "Period Locks"=>"SELECT Id,FromDay AS [From Date],ToDay AS [To Date],Locked,Reason FROM PeriodLock",
        "Statutory History"=>"SELECT Id,EffectiveDay AS [Effective Date],BasicPercent,EPFRate,EPFCeiling AS [EPF ceiling (INR)],CapEPF,EPFBasis,ESICRate,ESICCeiling AS [ESIC ceiling (INR)],ESICBasis,EPFRounding,ESICRounding,SalaryRounding FROM Statutory",
        "Alerts"=>"SELECT i.Id,'Invoice' AS Entity,i.Kind||' invoice due: '||i.Number AS Alert,i.DueDay AS [Due Date] FROM Invoice i JOIN Voucher v ON v.Id=i.VoucherId WHERE i.Cancelled=0 AND v.ReversedBy IS NULL AND i.DueDay<=@p1+30 AND i.Total>COALESCE((SELECT SUM(a.Amount) FROM Allocation a JOIN Voucher av ON av.Id=a.VoucherId WHERE a.InvoiceId=i.Id AND av.ReversedBy IS NULL),0) UNION ALL SELECT Id,'Instrument',Kind||' maturity / recovery: '||Number,COALESCE(MaturityDay,RecoveryDay) FROM Instrument WHERE Status='Active' AND COALESCE(MaturityDay,RecoveryDay)<=@p1+30 UNION ALL SELECT b.Id,'BG',CASE WHEN Status='Closed' THEN 'BG closed; lien pending: ' ELSE 'BG expiry: ' END||Number,ExpiryDay FROM BG b WHERE (Status='Active' AND ExpiryDay<=@p1+30) OR (Status='Closed' AND EXISTS(SELECT 1 FROM BGFD l WHERE l.BGId=b.Id AND l.ReleasedDay IS NULL)) UNION ALL SELECT r.Id,'PayrollRow','Salary pending: '||e.Name,p.Day FROM PayrollRow r JOIN Payroll p ON p.Id=r.PayrollId JOIN Employee e ON e.Id=r.EmployeeId WHERE p.Status='Finalized' AND r.Net>COALESCE((SELECT SUM(a.Amount) FROM SalaryAllocation a JOIN Voucher v ON v.Id=a.VoucherId WHERE a.PayrollRowId=r.Id AND v.Day<=@p1 AND (v.ReversedBy IS NULL OR (SELECT rv.Day FROM Voucher rv WHERE rv.Id=v.ReversedBy)>@p1)),0)",
        _=>throw new BusinessException("Choose a report.")};
    static string AdvanceQuery(string account)=>$"SELECT e.Id,e.Code,e.Name,s.Name AS Site,SUM(p.Amount) AS [Outstanding (INR)] FROM Posting p JOIN Voucher v ON v.Id=p.VoucherId JOIN Employee e ON e.Id=p.EmployeeId LEFT JOIN Site s ON s.Id=p.SiteId WHERE p.Account='{account}' AND v.Day<=@p1 GROUP BY e.Id,p.SiteId";
    static string InstrumentQuery(string kind)=>$"SELECT i.Id,i.Day AS Date,i.Number,i.Kind,e.Name AS Employee,i.Lender,i.Type,b.Name AS Bank,i.Principal AS [Principal / sanction (INR)],i.Rate,i.MaturityDay AS [Maturity Date],i.MaturityAmount AS [Maturity amount (INR)],i.EMI AS [EMI (INR)],i.RecoveryDay AS [Recovery / EMI Date],i.Installments,COALESCE((SELECT SUM(p.Amount)*{(kind=="Business Loan"?-1:1)} FROM Posting p JOIN Voucher v ON v.Id=p.VoucherId WHERE p.InstrumentId=i.Id AND p.Account='{(kind=="FD"?"FD":kind=="Business Loan"?"BLOAN":"ELOAN")}' AND v.Day<=@p1),0) AS [Outstanding (INR)],i.Status,i.ClosureDay AS [Closure Date],i.Remarks FROM Instrument i LEFT JOIN Employee e ON e.Id=i.EmployeeId LEFT JOIN Bank b ON b.Id=i.BankId WHERE i.Kind='{kind}'";
    static string GSTQuery(string kind,bool hsn)
    {
        string sign="((CASE WHEN v.Day BETWEEN @p0 AND @p1 THEN 1 ELSE 0 END)-(CASE WHEN rv.Day BETWEEN @p0 AND @p1 THEN 1 ELSE 0 END))";
        return $"SELECT {(hsn?"l.HSN":"l.GSTRate")} AS Id,l.GSTRate,SUM(l.Taxable*{sign}) AS [Taxable (INR)],SUM(l.CGST*{sign}) AS [CGST (INR)],SUM(l.SGST*{sign}) AS [SGST (INR)],SUM(l.IGST*{sign}) AS [IGST (INR)],i.ITC FROM InvoiceLine l JOIN Invoice i ON i.Id=l.InvoiceId JOIN Voucher v ON v.Id=i.VoucherId LEFT JOIN Voucher rv ON rv.Id=v.ReversedBy WHERE i.Kind='{kind}' AND (v.Day BETWEEN @p0 AND @p1 OR rv.Day BETWEEN @p0 AND @p1) GROUP BY {(hsn?"l.HSN,":"")}l.GSTRate,i.ITC";
    }
    DataTable EMISchedule(int from,int to,string search,int page,int pageSize)
    {
        var result=new DataTable();result.Columns.Add("Id",typeof(long));result.Columns.Add("Loan");result.Columns.Add("Installment",typeof(int));result.Columns.Add("Due Date",typeof(int));foreach(string k in new[]{"Opening","Payment","Principal","Interest","Closing"})result.Columns.Add(k+" (INR)",typeof(long));result.Columns.Add("Status");using var d=Open();long seq=0;
        foreach(DataRow r in d.Table("SELECT * FROM Instrument WHERE Kind='Business Loan' AND Status='Active' AND EMI>0 AND RecoveryDay IS NOT NULL").Rows){
            string number=Value.Text(r["Number"]);if(search!=""&&!number.Contains(search,StringComparison.OrdinalIgnoreCase))continue;long balance=-Balance(d,"BLOAN",instrument:Value.Long(r["Id"]),through:from-1);if(balance<=0)continue;
            var due=DateOnly.FromDayNumber((int)Value.Long(r["RecoveryDay"]));while(due.DayNumber<from)due=due.AddMonths(1);long emi=Value.Long(r["EMI"]);decimal rate=Value.Dec(r["Rate"]);
            for(int n=1;n<=600&&balance>0&&due.DayNumber<=to;n++,due=due.AddMonths(1)){
                long interest=Value.Money(Value.Rupees(balance)*rate/1200);if(emi<=interest){result.Rows.Add(++seq,number,n,due.DayNumber,balance,emi,0L,interest,balance,"EMI does not cover interest — revise terms");break;}
                long principal=Math.Min(balance,emi-interest);result.Rows.Add(++seq,number,n,due.DayNumber,balance,principal+interest,principal,interest,balance-principal,"Projection: monthly reducing balance; lender statement governs");balance-=principal;
            }
        }
        var output=result.Clone();foreach(var row in result.Rows.Cast<DataRow>().Skip(page*pageSize).Take(pageSize))output.ImportRow(row);return output;
    }
    public DataTable Report(string name,int from,int to,string search="",int page=0,int pageSize=200)
    {
        Authenticate();Value.Require(to>=from,"Check the report date range.");Value.Require(page>=0&&pageSize is >0 and <=10000,"Invalid report page.");if(name=="EMI Schedule")return EMISchedule(from,to,search,page,pageSize);using var d=Open();string sql=ReportSql(name);var schema=d.Table("SELECT * FROM ("+sql+") LIMIT 0",from,to);string where="";
        if(!string.IsNullOrWhiteSpace(search))where=" WHERE "+string.Join(" OR ",schema.Columns.Cast<DataColumn>().Where(c=>c.ColumnName!="Snapshot").Select(c=>$"instr(lower(CAST(\"{c.ColumnName.Replace("\"","\"\"")}\" AS TEXT)),lower(@p2))>0"));
        var result=d.Table("SELECT * FROM ("+sql+")"+where+" ORDER BY 1 DESC LIMIT @p3 OFFSET @p4",from,to,search,pageSize,page*pageSize);
        return result;
    }
    public Dictionary<string,long> Dashboard(int from,int through){Authenticate();using var d=Open();long bal(string a)=>Balance(d,a,through:through);long activity(string a)=>d.N("SELECT COALESCE(SUM(p.Amount),0) FROM Posting p JOIN Voucher v ON v.Id=p.VoucherId WHERE p.Account=@p0 AND v.Day BETWEEN @p1 AND @p2",a,from,through);
        return new(){["Sales"]=-activity("SALES"),["Purchases"]=activity("PURCHASE"),["Customer Receivable"]=bal("AR"),["Supplier Payable"]=-bal("AP"),["Bank Balance"]=d.N("SELECT COALESCE(SUM(p.Amount),0) FROM Posting p JOIN Bank b ON b.Id=p.BankId JOIN Voucher v ON v.Id=p.VoucherId WHERE b.Cash=0 AND p.Account='BANK' AND v.Day<=@p0",through),["Cash Balance"]=d.N("SELECT COALESCE(SUM(p.Amount),0) FROM Posting p JOIN Bank b ON b.Id=p.BankId JOIN Voucher v ON v.Id=p.VoucherId WHERE b.Cash=1 AND p.Account='BANK' AND v.Day<=@p0",through),["Salary Payable"]=-bal("SALARY"),["Staff Advance Outstanding"]=bal("STAFF"),["Employee Advance Outstanding"]=bal("ADV"),["Employee Loan Outstanding"]=bal("ELOAN"),["Total FD"]=bal("FD"),["FD Under Lien"]=d.N("SELECT COALESCE(SUM(p.Amount),0) FROM Posting p JOIN Voucher v ON v.Id=p.VoucherId WHERE p.Account='FD' AND v.Day<=@p0 AND EXISTS(SELECT 1 FROM BGFD l WHERE l.FDId=p.InstrumentId AND l.LinkedDay<=@p0 AND (l.ReleasedDay IS NULL OR l.ReleasedDay>@p0))",through),["Active BG Amount"]=d.N("SELECT COALESCE(SUM(Amount),0) FROM BG WHERE Day<=@p0 AND (ClosureDay IS NULL OR ClosureDay>@p0)",through),["Business Loan Outstanding"]=-bal("BLOAN")};
    }
    public static DataTable DisplayTable(DataTable raw)
    {
        var t=new DataTable();foreach(DataColumn c in raw.Columns)t.Columns.Add(c.ColumnName,typeof(string));
        foreach(DataRow r in raw.Rows){var row=t.NewRow();foreach(DataColumn c in raw.Columns){var x=r[c];string key=c.ColumnName;if(x is DBNull){row[key]="";continue;}
                if(key.EndsWith("(INR)"))row[key]=Value.Display(Value.Long(x));else if(key.EndsWith("Date")&&long.TryParse(Value.Text(x),out var day)&&day>0)row[key]=Value.Date((int)day);else if(key.EndsWith("Time")&&DateTimeOffset.TryParse(Value.Text(x),out var tm))row[key]=tm.ToLocalTime().ToString("dd-MM-yyyy HH:mm:ss");else if(key=="Snapshot"){var p=JsonSerializer.Deserialize<PayrollResult>(Value.Text(x));row[key]=p is null?"":$"Days {p.PayableDays}/{p.CalendarDays}; Sundays {p.Sundays}; earned {Value.Display(p.Earned)}; basic {Value.Display(p.Basic)}; allowance {Value.Display(p.Allowance)}; EPF {Value.Display(p.EPF)}; ESIC {Value.Display(p.ESIC)}; advance {Value.Display(p.Advance)}; loan {Value.Display(p.LoanRecovery)}";}else row[key]=Value.Text(x);}t.Rows.Add(row);}return t;
    }
}
